  var daysInMonth=new Date(curYear,curMonth,0).getDate();
  var cells='';
  for(var i=0;i<startDow;i++)cells+='<div class="wt-cell empty"></div>';
  for(var dnum=1;dnum<=daysInMonth;dnum++){
    var ds=curYear+'-'+pad(curMonth)+'-'+pad(dnum);
