    var dotsHtml=evs.slice(0,3).map(function(e){return '<span class="wt-dot" style="background:'+evType(e.type).c+'"></span>'}).join('');
    var more=evs.length>3?'<span class="wt-more">+'+(evs.length-3)+'</span>':'';
